import React,{useState} from 'react';
import {View,TextInput,Button,Text} from 'react-native';
export default function Forgot(){
  const[e,setE]=useState('');const[m,setM]=useState('');
  const send=async()=>{try{const r=await fetch('{{api_url}}/forgot',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:e})});setM(r.ok?'sent':'err');}catch{setM('err');}};
  return(<View style={{padding:24}}><TextInput placeholder='email' value={e} onChangeText={setE} style={{borderWidth:1,padding:8,marginBottom:12}}/><Button title='Send reset link' onPress={send}/><Text>{m}</Text></View>);}
